-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.skill_check(p_skill double precision, p_difficulty double precision, p_tool_ql double precision DEFAULT 0, p_ease double precision DEFAULT 0)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
begin
  if coalesce(current_setting('wildermon.foreknow', true), '') = 'on' then
    perform set_config('wildermon.foreknown', 'on', true);
    return true;
  end if;
  return random() < least(0.98, greatest(0.3,
    0.6 + (p_skill / 100) * 0.38 + p_tool_ql / 500
      - (case when p_ease > 0 then greatest(p_difficulty * 0.5, p_difficulty - p_ease) else p_difficulty end) / 150));
end $function$
